// ==UserScript==
// @name         VN Flag
// @version      1.0.4
// @match        *://*/*
// @grant        none
// @run-at       document-idle
// ==/UserScript==

(function() {
  'use strict';

  const TARGET_NAME = "Phan Đình Huy";

  // Cấu trúc Lá cờ SVG vector kèm hiệu ứng sóng lượn (Flag Wave Animation)
