  (document.head || document.documentElement).appendChild(style);

  function replaceDoctorName() {
    const links = document.querySelectorAll('#table_header .header_right a.mau');
    links.forEach(a => {
      if ((a.textContent.trim() === TARGET_NAME || a.textContent.includes(TARGET_NAME)) && !a.dataset.customBadge) {
        a.innerHTML = BADGE_HTML;
        a.dataset.customBadge = "true";
